mc(d,18,'Answer Relevancy dùng reverse-question generation để tránh nhầm lẫn nào của cosine Q–A trực tiếp?','Cùng entity/từ khóa chưa có nghĩa answer trả đúng điều được hỏi','Cosine cao luôn chứng minh answer đủ thông tin','Answer phải lặp nguyên question mới relevant','Mọi paraphrase của câu trả lời đều off-topic','Reverse questions biểu diễn câu hỏi mà answer thực sự giải đáp, rồi so với question gốc để tách cùng chủ đề khỏi đúng trọng tâm.')
mc(d,20,'Context Recall cần ground-truth answer để đánh giá điều gì?','Các ý cần thiết của đáp án chuẩn có được retrieved context hỗ trợ','Chỉ response có bám context đã lấy dù thiếu thông tin','Chỉ độ dài answer so với question','Chỉ JSON output có parse được','Recall kiểm coverage các ý đáp án cần thiết; thiếu reference khó biết context đã lấy có bỏ sót ý phải có hay không.')
mc(d,22,'Traffic thật chủ yếu cần tổng hợp nhiều context nhưng test set đa số câu một chunk. Cần sửa thiết kế nào?','Điều chỉnh phân bố loại câu hỏi theo traffic và review dữ liệu sinh','Chỉ tăng số câu một chunk để score ổn định hơn','Giữ nguyên distribution vì default luôn đại diện mọi sản phẩm','Chỉ đổi judge để che khoảng trống coverage','Synthetic test distribution phải phản ánh user behavior; default nhiều simple có thể che lỗi multi-context.','apply')
mc(d,23,'Đổi judge model và nâng RAGAS version cùng lúc có thể làm so sánh score trước/sau sai ở đâu?','Scoring/judge thay đổi nên delta không chỉ do hệ RAG','Mọi version luôn cùng scoring nên delta chắc do model','Chỉ số lượng câu hỏi mới tác động score','Nếu API đều 200 thì baseline không cần đo lại','Pin judge/framework version và log metadata giúp so sánh; upgrade major cần đo baseline/regression lại.')
mc(d,29,'Pairwise evaluation phù hợp loại quyết định nào hơn absolute score đơn lẻ?','So phiên bản mới với baseline để xét regression','Giám sát xu hướng không có response baseline nào','Đo số byte vector storage','Thay mọi rubric bằng model name','Pairwise chọn A/B/tie dựa cùng đầu vào; absolute score theo rubric hữu ích theo dõi trend nhưng dễ subjective drift.')
mc(d,32,'Một judge thường ưu ái output của cùng họ model khi chọn production model. Cần giảm bias nào?','Self-enhancement bằng cross-judge khác family','Chỉ position bias bằng đổi chỗ A và B','Chỉ temperature cao để judge đa dạng','Chỉ lấy judge cùng model để đồng bộ style','Cross-judge tránh một model tự ưu ái fingerprint/style của nó khi so chất lượng các model.')
mc(d,33,'Hai answer cùng nội dung nhưng markdown được chấm cao hơn prose dù UI không render Markdown. Cách giảm nhiễu nào phù hợp?','Strip formatting hoặc rubric yêu cầu chỉ chấm content','Ép mọi answer nhiều header hơn để tối đa điểm','Coi formatting score là business outcome không cần kiểm','Bỏ toàn bộ answer plain text khỏi eval','Style/verbosity bias thưởng vẻ chuyên nghiệp ngoài nội dung; normalization và rubric rõ giúp giảm bias.','apply')
mc(d,34,'Cohen’s kappa bổ sung gì so với tỷ lệ đồng ý thô human–judge?','Điều chỉnh phần agreement có thể xảy ra do ngẫu nhiên','Chỉ đo độ dài trung bình answer','Chỉ đo latency chấm điểm','Tự chứng minh judge không có mọi bias','Kappa đo agreement sau khi xét chance agreement; human calibration cần trước dùng judge cho quyết định tự động.')
mc(d,35,'Tiered judge tiết kiệm bằng cách dành model mạnh cho nhóm nào?','Các case khó/borderline sau heuristic và judge nhỏ','Mọi query kể cả schema lỗi rõ ràng','Chỉ query đã được model nhỏ chắc chắn đúng','Không case nào vì heuristic luôn đủ','Tầng rẻ bắt lỗi cấu trúc rộng, semantic judge nhỏ rồi escalate case khó để giữ chi phí hợp lý.')
mc(d,37,'Answer nói số nhân viên khác trực tiếp con số context cung cấp thuộc loại hallucination nào?','Intrinsic: mâu thuẫn với context','Extrinsic: chỉ thêm fact ngoài context mà không mâu thuẫn','Không phải hallucination nếu cùng công ty','Chỉ lỗi format không cần kiểm fact','Intrinsic trái bằng chứng đang có, khác extrinsic bổ sung thông tin không xuất hiện trong context.')
mc(d,38,'SelfCheckGPT tìm tín hiệu hallucination bằng cách nào?','So mức nhất quán của nhiều sample answer cho cùng question','Chỉ tin answer đầu vì temperature 0','Chỉ so độ dài response với max_tokens','Chỉ kiểm URL citation có 200','Sample outputs có thể bất nhất ở phần hallucinated; phương pháp reference-free nhưng thêm generation cost và không phải proof chắc chắn.')
mc(d,40,'Semantic entropy khác string-level entropy ở cách nhóm answer nào?','Gộp các paraphrase cùng nghĩa trước khi đo bất định','Mỗi cách viết khác nhau luôn là fact khác nhau','Chỉ nhóm bằng độ dài token','Bỏ mọi answer không cùng chuỗi ký tự','Paraphrase khác chữ nhưng cùng fact không nên bị coi là bất định ngữ nghĩa; entropy trên semantic clusters phân biệt wording và meaning.')
mc(d,39,'Trong NLI hallucination check, premise và hypothesis nên lấy từ đâu?','Retrieved context và từng sentence/claim trong answer','Question và model name làm hai input','Chỉ answer chấm chính nó không context','Chỉ system prompt và token budget','Context là bằng chứng premise, claim answer là hypothesis để xét entailment/contradiction/neutral.')
mc(d,46,'Validator timeout nên fail-open hay fail-closed được quyết định theo điều gì?','Risk của tác vụ và chính sách đã định','Luôn fail-open cho mọi sensitive action','Luôn xem timeout là approval của human','Chỉ chọn ngẫu nhiên để chia đều traffic','Timeout là failure của control; allow/block cần theo risk, không nhầm không chấm được với an toàn đã xác nhận.')
mc(d,69,'Presidio mặc định bỏ sót CCCD/số điện thoại Việt Nam. Hướng sửa nào phù hợp?','Thêm recognizer/regex phù hợp Việt Nam hoặc mô hình NER phù hợp','Chỉ tăng output tokens của model','Chỉ dịch mọi số thành văn bản tiếng Anh','Bỏ input PII check vì không hỗ trợ mọi ngôn ngữ','PII locale-specific cần custom recognition; default en-only không đủ cho trường dữ liệu Việt Nam.','apply')
mc(d,54,'Một malicious turn đã bị chặn output nhưng vẫn nằm trong history. Defense cần thay đổi ở đâu?','Sanitize/replace input độc trong history trước khi model đọc lại','Chỉ chặn output turn đó rồi tin history sạch','Chỉ thêm TTL cho cache ngắn hơn','Chỉ đổi model mạnh hơn để không đọc history','Session poisoning khai thác input độc còn trong history; input-level replacement ngăn “continue earlier” kích hoạt lại.','apply')
mc(d,56,'Execution rails khác retrieval rails ở đối tượng kiểm tra nào?','Tool call/args trước thực thi thay retrieved documents trước đưa vào LLM','Cả hai chỉ chấm post-hoc final answer','Execution rails chỉ đổi topic flow','Retrieval rails cấp quyền mọi tool nếu doc đúng','Rails theo tầng: dialog cho flow/topic, retrieval cho doc, execution cho tool validation trước side effect.')
