mc(d,9,'Nhiều client cùng retry khi provider timeout có thể biến lỗi nhỏ thành outage thế nào?','Retry storm cạn quota/rate limit và dồn tải thêm','Retry tự giảm tải provider theo số client','Mỗi retry luôn được miễn quota nên không cascade','Chỉ output answer quality thay đổi, hệ thống không ảnh hưởng','Retry không bounded/breaker/fallback/budget có thể khuếch đại failure thay phục hồi.')
mc(d,10,'Error rate 0% nhưng faithfulness giảm dần cho thấy uptime SLO thiếu chiều gì?','Quality SLO cho hành vi câu trả lời','Chỉ số lượng pod đang running','Chỉ capacity reserved theo năm','Chỉ sốport health check','Silent degradation có thể do model/prompt/KB/cache đổi mà không exception; reliability phải đo quality cùng availability.')
mc(d,12,'HALF-OPEN trong circuit breaker nhằm mục đích gì?','Thử probe có kiểm soát để xem dependency đã phục hồi','Cho toàn traffic quay lại ngay bất kể kết quả','Chặn vĩnh viễn mọi lời gọi như đã xóa provider','Đổi provider mà không cần kiểm health','Sau reset timeout, probe đánh giá recovery trước khi trở về CLOSED hoặc OPEN lại.')
mc(d,13,'Vì sao cần định nghĩa exception nào được tính là breaker failure?','Không phải mọi lỗi ứng dụng đều phản ánh dependency đang hỏng','Mọi validation error của user luôn phải làm provider OPEN','Chỉ đếm status 200 là failure để thử breaker','Không cần vì exception nào cũng giống nhau','Failure classification quyết định breaker trip đúng; cấu hình threshold/reset/success cùng semantics lỗi cần rõ.')
mc(d,13,'Gateway nhiều instance chỉ giữ circuit state trong memory riêng có rủi ro gì?','Các replica không phối hợp trạng thái dependency đang lỗi','State tự đồng bộ nhờ cùng model name','Mọi instance luôn thấy cùng failure counter mà không backend','Không thể có retry storm vì đã có class CircuitBreaker','Production multi-instance nên có backend chung như Redis để chia sẻ trạng thái breaker phù hợp.')
mc(d,14,'Backup provider trả JSON được nhưng không hỗ trợ tool calling mà task cần. Điều gì phải được kiểm trước khi fallback?','Feature compatibility với yêu cầu task','Chỉ backup có giá rẻ hơn','Chỉ model cùng kích thước params','Chỉ HTTP endpoint phản hồi 200','Fallback không chỉ đổi model; cần JSON/tool/context/latency/cost/policy semantics tương thích.','apply')
